import { chromium } from '@playwright/test'

const TOKEN = 'eb0abcfe-8e50-4e1f-bf96-e193465b03b5'
const BASE = 'http://localhost:8098'
const log = (...a) => console.log('[probe]', ...a)

const exe = process.env.PW_CHROME_PATH || `${process.env.LOCALAPPDATA}\\ms-playwright\\chromium-1243\\chrome-win64\\chrome.exe`

const browser = await chromium.launch({ headless: true, executablePath: exe })
const ctx = await browser.newContext({ baseURL: BASE, viewport: { width: 1600, height: 1000 } })
const page = await ctx.newPage()

const reqs = []
page.on('request', (r) => {
  const u = r.url()
  if (u.includes('todoTaskList') || u.includes('listBusCodeMenu')) {
    reqs.push({ url: u, method: r.method(), postData: r.postData() })
  }
})
page.on('response', async (r) => {
  const u = r.url()
  if (u.includes('todoTaskList')) {
    try { const j = await r.json(); log('todoTaskList resp total=', j.total) } catch {}
  }
})

// inject token into sessionStorage before app boots
await page.addInitScript((token) => {
  sessionStorage.setItem('Admin-Token', token)
}, TOKEN)

await page.goto('/#/todo', { waitUntil: 'domcontentloaded' })
await page.waitForTimeout(6000)

log('URL', page.url())
log('has search form', await page.locator('.search-form-container').count())

// find the 业务类型 select input
const selectInput = page.locator('.search-form-container .el-select input').first()
const cnt = await selectInput.count()
log('select input count', cnt)
if (cnt) {
  await selectInput.click()
  await page.waitForTimeout(500)
  await selectInput.fill('账户开户')
  await page.waitForTimeout(1500)
  // capture displayed value in input after typing
  log('input value after type:', await selectInput.inputValue())
  // capture dropdown options
  const opts = await page.locator('.el-select-dropdown__item').allInnerTexts()
  log('dropdown options:', JSON.stringify(opts))
  // click 搜索 button
  const searchBtn = page.locator('.button-col button, .single-line-buttons button').filter({ hasText: '搜索' }).first()
  const sbc = await searchBtn.count()
  log('search btn count', sbc)
  if (sbc) {
    await searchBtn.click()
    await page.waitForTimeout(2000)
    log('input value AFTER search (no select):', await selectInput.inputValue())
  }

  // Now test: type then select the option, then search
  await selectInput.click()
  await page.waitForTimeout(300)
  await selectInput.fill('账户开户')
  await page.waitForTimeout(1500)
  const firstOpt = page.locator('.el-select-dropdown__item').filter({ hasText: '账户开户' }).first()
  if (await firstOpt.count()) {
    await firstOpt.click()
    await page.waitForTimeout(500)
    log('input value after SELECT:', await selectInput.inputValue())
    if (sbc) {
      await searchBtn.click()
      await page.waitForTimeout(2500)
      log('input value AFTER search (selected):', await selectInput.inputValue())
    }
  } else {
    log('no exact option 账户开户 in dropdown')
  }
}

log('=== captured requests ===')
for (const r of reqs) log(r.method, r.url.replace(BASE,''), 'body=', r.postData)

await page.screenshot({ path: '.dsh_tmp/probe-5980.png', fullPage: false })
await browser.close()

