import { chromium } from '@playwright/test'

const TOKEN = process.env.ARG_TOKEN || 'eb0abcfe-8e50-4e1f-bf96-e193465b03b5'
const BASE = 'http://localhost:8098'
const log = (...a) => console.log('[probe]', ...a)
const exe = process.env.PW_CHROME_PATH || `${process.env.LOCALAPPDATA}\\ms-playwright\\chromium-1243\\chrome-win64\\chrome.exe`

const browser = await chromium.launch({ headless: true, executablePath: exe })
const ctx = await browser.newContext({ baseURL: BASE, viewport: { width: 1600, height: 1000 } })
const page = await ctx.newPage()

const reqs = []
page.on('request', (r) => {
  const u = r.url()
  if (u.includes('todoTaskList') || u.includes('listBusCodeMenu')) reqs.push({ u, m: r.method(), b: r.postData() })
})
page.on('response', async (r) => {
  if (r.url().includes('todoTaskList')) { try { const j = await r.json(); log('RESP todoTaskList total=', j.total) } catch {} }
})

// 1) load origin (login page), then set token in sessionStorage, then navigate
await page.goto('/#/login', { waitUntil: 'domcontentloaded' })
await page.evaluate((t) => { sessionStorage.setItem('Admin-Token', t) }, TOKEN)
await page.goto('/#/todo', { waitUntil: 'domcontentloaded' })
await page.waitForTimeout(7000)
log('URL', page.url())
log('search form count', await page.locator('.search-form-container').count())

const selectInput = page.locator('.search-form-container .el-select input').first()
if (await selectInput.count()) {
  await selectInput.click(); await page.waitForTimeout(400)
  await selectInput.fill('账户开户'); await page.waitForTimeout(1600)
  log('A) after type, input value:', JSON.stringify(await selectInput.inputValue()))
  log('   dropdown options:', JSON.stringify(await page.locator('.el-select-dropdown__item').allInnerTexts()))
  const searchBtn = page.locator('.single-line-buttons button, .button-col button').filter({ hasText: '搜索' }).first()
  log('   search btn count', await searchBtn.count())
  if (await searchBtn.count()) {
    await searchBtn.click(); await page.waitForTimeout(2000)
    log('B) after 查询 (typed, NOT selected) input value:', JSON.stringify(await selectInput.inputValue()))
  }
  // C) type + select + search
  await selectInput.click(); await page.waitForTimeout(300)
  await selectInput.fill('账户开户'); await page.waitForTimeout(1600)
  const opt = page.locator('.el-select-dropdown__item').filter({ hasText: '账户开户' }).first()
  if (await opt.count()) {
    await opt.click(); await page.waitForTimeout(600)
    log('C1) after SELECT input value:', JSON.stringify(await selectInput.inputValue()))
    if (await searchBtn.count()) {
      await searchBtn.click(); await page.waitForTimeout(2500)
      log('C2) after 查询 (SELECTED) input value:', JSON.stringify(await selectInput.inputValue()))
    }
  } else log('C) no 账户开户 option')
} else log('no select input found')

log('=== requests ===')
for (const r of reqs) log(r.m, r.u.replace(BASE, ''), 'body=', r.b)
await page.screenshot({ path: '.dsh_tmp/probe-5980.png' })
await browser.close()
